{"command": "python3 << 'EOF'
import json

for q in ['q01','q02','q03','q04','q05']:
    d = json.load(open(f'/app/output/{q}.json'))
    print(f"=== {q}.json validates ===")
    if q == 'q01':
        assert 'ramp_rate_limit_c_per_s' in d
        assert 'violating_runs' in d and d['violating_runs'] == sorted(d['violating_runs'])
        assert 'max_ramp_by_run' in d
        assert list(d['max_ramp_by_run'].keys()) == sorted(d['max_ramp_by_run'].keys())
        for rid, v in d['max_ramp_by_run'].items():
            assert set(v.keys()) == {'tc_id', 'max_preheat_ramp_c_per_s'}
    elif q == 'q02':
        rids = [r['run_id'] for r in d]
        assert rids == sorted(rids)
        for r in d:
            assert set(r.keys()) == {'run_id','tc_id','tal_s','required_min_tal_s','required_max_tal_s','status'}
            assert r['status'] in ('compliant', 'non-compliant')
    elif q == 'q03':
        assert d['failing_runs'] == sorted(d['failing_runs'])
        assert list(d['min_peak_by_run'].keys()) == sorted(d['min_peak_by_run'].keys())
        for rid, v in d['min_peak_by_run'].items():
            assert set(v.keys()) == {'tc_id','peak_temp_c','required_min_peak_c'}
    elif q == 'q04':
        rids = [r['run_id'] for r in d]
        assert rids == sorted(rids)
        for r in d:
            assert set(r.keys()) == {'run_id','required_min_speed_cm_min','actual_speed_cm_min','meets'}
            assert isinstance(r['meets'], bool)
    elif q == 'q05':
        fams = [r['board_family'] for r in d]
        assert fams == sorted(fams)
        for r in d:
            assert set(r.keys()) == {'board_family','best_run_id','runner_up_run_ids'}
            assert r['runner_up_run_ids'] == sorted(r['runner_up_run_ids'])
    print(f"  OK")

# Spot-check one computation: Q1 for R0001
import pandas as pd
tc = pd.read_csv('/app/data/thermocouples.csv')
g = tc[(tc['run_id']=='R0001') & (tc['tc_id']=='TC1')].sort_values('time_s')
t = g['time_s'].to_numpy(float); y = g['temp_c'].to_numpy(float)
best = None
for i in range(1,len(t)):
    if 100<=y[i-1]<=150 and 100<=y[i]<=150 and t[i]>t[i-1]:
        s = (y[i]-y[i-1])/(t[i]-t[i-1])
        best = s if best is None else max(best,s)
print(f"\nSanity check R0001/TC1 max preheat ramp (recompute): {best:.4f}")
print(f"q01 says: {json.load(open('/app/output/q01.json'))['max_ramp_by_run']['R0001']}")
EOF", "summary": "Validate output format and sanity-check computation"}

